insert into projects (phase_id, concept_id, title, description, project_type) values
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'Profile Card', 'Store your name, age, and favorite language in variables of different types (str, int, bool) and print them.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'Commented Greeting', 'Write a short script that prints a multi-line greeting, with comments explaining each line.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000003', 'Tip Calculator', 'Given a bill amount and tip percentage, compute and print the tip and total using +, -, *, /, //, %, and **.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000004', 'Initials Extractor', 'Given a full name string, use indexing and slicing to print the person''s initials.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000005', 'Text Cleaner', 'Take a messy string with extra whitespace and inconsistent casing, and normalize it using string methods.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000006', 'Receipt Printer', 'Use f-strings to format a shopping receipt with aligned prices and two decimal places.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000007', 'Access Checker', 'Write expressions that combine comparison and logical operators to decide if a user (given age and membership status) can access a feature.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000008', 'Mad Libs', 'Prompt the user for a few words with input() and combine them into a silly sentence.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000009', 'Grade Converter', 'Convert a numeric score to a letter grade using if/elif/else.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000010', 'Number Guessing Game', 'Use a while loop to keep prompting the user to guess a fixed number until they get it right.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000011', 'Multiplication Table', 'Print a multiplication table for a given number using a for loop over range().', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000012', 'Unit Converter Functions', 'Write functions like celsius_to_fahrenheit(c) that take a parameter and return a converted value.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000013', 'Score Tracker', 'Write a function that updates a running total, and demonstrate the difference between a local variable shadowing a global one.', 'micro'),
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000014', 'Safe Input Parser', 'Prompt for a number and use try/except to handle invalid (non-numeric) input gracefully instead of crashing.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000015', 'Shopping List Manager', 'Build a list of grocery items and add/remove/update entries by index.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000016', 'Playlist Snippets', 'Given a list of song titles, use slicing to print the first 3, last 3, and every other song.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000017', 'Leaderboard', 'Maintain a list of scores, adding new ones with append(), removing the lowest with pop/remove, and sorting with sort().', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000018', 'Coordinate Pairs', 'Store a list of (x, y) tuples representing points, and write a function that returns the point farthest from the origin.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000019', 'Contact Book', 'Build a dict mapping names to phone numbers, and add/update/remove/look up entries.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000020', 'Inventory Report', 'Given a dict of item -> quantity, iterate with .items() to print a formatted inventory report and total count.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000021', 'Class Roster Overlap', 'Given two sets of student names, find who''s in both classes, only one, or either, using set operations.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000022', 'Squares and Filters', 'Use comprehensions to build a list of squares, a dict of word lengths, and a set of unique vowels from a sentence.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000023', 'Student Records', 'Model a list of dicts (each with name and a grades list) and compute each student''s average grade.', 'micro'),
  ('00000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000024', 'Word Frequency Counter', 'Use collections.Counter to find the most common words in a paragraph, and namedtuple to represent a Point.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000025', 'Pet Class', 'Define a Pet class and create a few instances with different names.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000026', 'Bank Account', 'Create a BankAccount class with __init__ storing an owner name and starting balance.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000027', 'Bank Account Operations', 'Add deposit() and withdraw() methods to your BankAccount class that update self.balance.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000028', 'Account Counter', 'Add a class attribute tracking how many BankAccount instances have been created, updated via a classmethod.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000029', 'Interest Calculator', 'Add a @staticmethod to BankAccount that computes interest for a given balance and rate, without needing an instance.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000030', 'Savings Account Subclass', 'Create a SavingsAccount that inherits from BankAccount and overrides withdraw() to enforce a minimum balance.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000031', 'Car Has an Engine', 'Model a Car class that holds an Engine instance and delegates start()/stop() calls to it.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000032', 'Printable Accounts', 'Add __str__ to BankAccount so printing an instance shows a friendly summary, and __eq__ to compare two accounts by balance.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000033', 'Validated Balance', 'Turn balance into a @property that raises an error if you try to set it negative.', 'micro'),
  ('00000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000034', 'Shape Interface', 'Define an abstract Shape base class with an abstract area() method, then implement Circle and Square subclasses.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000035', 'Custom Countdown Iterator', 'Implement a Countdown class with __iter__ and __next__ that counts down from n to 0.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000036', 'Fibonacci Generator', 'Write a generator function that yields Fibonacci numbers one at a time, lazily.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000037', 'Timer Context Manager', 'Write a context manager (class-based or @contextmanager) that prints how long a block of code took to run.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000038', 'Logging Decorator', 'Write a @log_calls decorator that prints a function''s name and arguments every time it''s called.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000039', 'Combinations Explorer', 'Use itertools.combinations and itertools.product to explore possible pairings from a small list.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000040', 'Memoized Fibonacci', 'Speed up a recursive Fibonacci function with @functools.lru_cache and compare timing.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000041', 'Directory Lister', 'Use pathlib.Path to list all .txt files in a directory and print their sizes.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000042', 'Age Calculator', 'Given a birthdate string, use datetime to compute the person''s age in years.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000043', 'Config Loader', 'Write a small config dict, save it to a JSON string with json.dumps, then load it back with json.loads.', 'micro'),
  ('00000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000044', 'Phone Number Finder', 'Use re.findall to extract all phone numbers from a block of text.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000045', 'Test Your Converters', 'Write pytest tests for the unit-converter functions from Phase 1.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000046', 'Type-Annotate a Module', 'Add type hints to every function in one of your earlier scripts and run mypy on it.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000047', 'Isolated Project Setup', 'Create a fresh virtual environment, install one package into it, and write a requirements.txt.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000048', 'Clean Up a Messy Script', 'Run ruff/black on a deliberately messy script and fix every warning.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000049', 'Replace prints with Logging', 'Swap out print() debugging in an earlier script for proper logging.getLogger() calls at different levels.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000050', 'Package Your Utility Library', 'Turn the decorator library from Phase 4 into an installable package with a pyproject.toml.', 'micro'),
  ('00000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000051', 'Feature Branch Practice', 'Make a small change to any earlier project on a feature branch, commit it with a clear message, and merge it.', 'micro'),
  ('00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000052', 'Three Ways to Fetch', 'Fetch the same 5 URLs sequentially, with threads, and with asyncio, and compare the timings.', 'micro'),
  ('00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000053', 'Find the Bottleneck', 'Profile a deliberately slow script with cProfile and identify which function eats the most time.', 'micro'),
  ('00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000054', 'Reference Counting Demo', 'Use sys.getrefcount and a small object graph to observe how references keep objects alive.', 'micro'),
  ('00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000055', 'Persisted Contact Book', 'Rewrite the Phase 2 Contact Book to store contacts in a SQLite database instead of a dict.', 'micro'),
  ('00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000056', 'Weather Fetcher', 'Use the requests library to fetch and print data from a public JSON API.', 'micro'),
  ('00000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000057', 'Tiny Echo Server', 'Write a minimal TCP socket server that echoes back whatever a client sends it.', 'micro'),
  ('00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000058', 'Track Decision Doc', 'Write a one-page comparison of two candidate tracks (e.g. web backend vs data) and pick one with reasons.', 'micro'),
  ('00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000059', 'Hello, Framework', 'Build the smallest possible "hello world" in your chosen framework (one route, one command, or one DataFrame op).', 'micro'),
  ('00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000060', 'Validated User Model', 'Define a Pydantic model for a user signup form and test it against valid and invalid input.', 'micro'),
  ('00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000061', 'Dockerize a Script', 'Write a Dockerfile that packages one of your earlier scripts and runs it in a container.', 'micro'),
  ('00000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000062', 'First OSS Read', 'Pick a small open-source Python repo, read through one module, and write a short summary of what you learned from its style.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000063', 'Complexity Audit', 'Take three functions you''ve already written and annotate each with its time and space complexity.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000064', 'Implement Binary Search', 'Implement binary search by hand (no built-ins) and test it against Python''s bisect module.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000065', 'Recursive Directory Size', 'Write a recursive function that sums the sizes of all files under a directory tree.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000066', 'Balanced Brackets Checker', 'Use a stack to check whether a string of brackets is balanced, without looking at the Phase 8 challenge for it.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000067', 'Binary Tree Depth', 'Build a simple binary tree class and write a function to compute its maximum depth.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000068', 'Top-K Scores', 'Use heapq to efficiently find the top 3 scores from a large list.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000069', 'Longest Unique Substring', 'Find the longest substring without repeating characters using a sliding window.', 'micro'),
  ('00000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000070', 'Narrate a Solve', 'Pick one earlier challenge and write out your clarify -> approach -> code -> test process as if explaining it in an interview.', 'micro'),
  ('00000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000071', 'Capstone One-Pager', 'Write a one-page scope doc for your capstone: problem, users, core features, explicit non-goals.', 'micro'),
  ('00000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000072', 'Architecture Sketch', 'Diagram (even in ASCII or a simple description) how your capstone''s pieces fit together and why.', 'micro'),
  ('00000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000073', 'CI Pipeline', 'Set up a GitHub Actions workflow that runs your capstone''s test suite on every push.', 'micro'),
  ('00000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000074', 'Ship It', 'Deploy your capstone somewhere reachable (even a free tier) and add one basic health-check or log line.', 'micro'),
  ('00000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000075', 'Capstone README', 'Write a README for your capstone covering what it does, how to run it, and what you''d do differently next time.', 'micro');
